pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C(0, "", "");
    }

    function _run(uint256 v, uint256 w, address target) internal {
        uint256 s0;
        try c.totalSupply() returns (uint256 __r) { s0 = __r; } catch { return; }
        vm.assume(target != address(0));
        vm.assume(w <= s0);
        vm.assume(v <= w);
        uint256 b0;
        try c.balanceOf(target) returns (uint256 __r) { b0 = __r; } catch { return; }
        try c.mintToken(target, w) {} catch { return; }
        try c.transfer(target, v) {} catch { return; }
        try c.burn(w) {} catch { return; }
